# Which vault key (namespace `movies`) feeds which GitHub Actions secret. NAMES ONLY.
# Pushed by infra/bin/push-gh-secrets. The vault is the source of truth; Actions secrets are copies.
# A row whose vault key does not exist yet is skipped. (GitHub never reveals a secret, so there is
# no "up to date" check here: a push always overwrites; push only what you have rotated.)
#
# <owner/repo>  <ACTIONS_SECRET>  <VAULT_KEY>
pawelkrupinski/movies  NIX_STAGE_SSH_KEY               NIX_STAGE_SSH_KEY
pawelkrupinski/movies  NIX_STAGE_SIGNING_KEY           NIX_STAGE_SIGNING_KEY
pawelkrupinski/movies  MONGO_CI_SSH_KEY                MONGO_CI_SSH_KEY
pawelkrupinski/movies  TMDB_API_KEY                    TMDB_API_KEY
pawelkrupinski/movies  DECODO_PROXY_USER               DECODO_PROXY_USER
pawelkrupinski/movies  DECODO_PROXY_PASS               DECODO_PROXY_PASS
pawelkrupinski/movies  GRAFANA_ANNOTATION_TOKEN        GRAFANA_ANNOTATION_TOKEN
pawelkrupinski/movies  SYNC_PR_APP_PRIVATE_KEY         SYNC_PR_APP_PRIVATE_KEY
pawelkrupinski/movies  KINOWO_RELEASE_KEYSTORE_BASE64  KINOWO_RELEASE_KEYSTORE_BASE64
pawelkrupinski/movies  KINOWO_RELEASE_KEY_ALIAS        KINOWO_RELEASE_KEY_ALIAS
pawelkrupinski/movies  KINOWO_RELEASE_KEY_PASSWORD     KINOWO_RELEASE_KEY_PASSWORD
pawelkrupinski/movies  KINOWO_RELEASE_STORE_PASSWORD   KINOWO_RELEASE_STORE_PASSWORD
pawelkrupinski/movies  OMDB_API_KEY                    OMDB_API_KEY
# The push credential for registry.kinowo.net (infra/nix/modules/roles/registry.nix). Read by ci.yml and
# main.yml only on the self-hosted Forgejo, where the IMAGE_REPO variable points pushes there.
pawelkrupinski/movies  REGISTRY_PASSWORD               REGISTRY_PUSH_PASSWORD
